  /* Header */
  .report-header {
    border-bottom: 1px solid var(--border);
    padding-bottom: 28px;
    margin-bottom: 36px;
  }
  .report-header .tag {
    display: inline-block;
    font-size: 11px;
    font-weight: 600;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--accent);
    border: 1px solid var(--accent);
    border-radius: 4px;
    padding: 2px 8px;
    margin-bottom: 14px;
  }
  .report-header h1 {
    font-size: 30px;
    font-weight: 700;
    color: var(--text);
    line-height: 1.25;
    margin-bottom: 10px;
  }
  .report-header .subtitle {
    color: var(--text-muted);
    font-size: 15px;
    max-width: 800px;
  }
  .report-header .meta {
    margin-top: 14px;
    display: flex;
    gap: 24px;
    font-size: 12px;
    color: var(--text-dim);
  }
  .report-header .meta span strong { color: var(--text-muted); }

  /* KPI Block */
  .kpi-grid {
    display: grid;
    grid-template-columns: repeat(5, 1fr);
    gap: 12px;
    margin-bottom: 40px;
