  .kpi-label {
    font-size: 11px;
    font-weight: 600;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: var(--text-dim);
    margin-bottom: 6px;
  }
  .kpi-value {
    font-size: 28px;
    font-weight: 700;
    line-height: 1.1;
    color: var(--text);
    margin-bottom: 4px;
  }
  .kpi-value.blue { color: var(--accent); }
  .kpi-value.green { color: var(--accent2); }
  .kpi-value.orange { color: var(--accent5); }
  .kpi-value.purple { color: var(--accent4); }
  .kpi-value.red { color: var(--accent3); }
  .kpi-note { font-size: 11px; color: var(--text-dim); }

  /* Section */
  .section {
    margin-bottom: 52px;
  }
  .section-header {
    display: flex;
    align-items: baseline;
    gap: 10px;
    margin-bottom: 6px;
  }
  .section-num {
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    color: var(--text-dim);
    min-width: 28px;
  }
  .section h2 {
    font-size: 19px;
    font-weight: 700;
    color: var(--text);
    margin-bottom: 0;
  }
  .section-divider {
    height: 1px;
    background: var(--border);
    margin: 10px 0 20px;
  }
  .section p {
    color: var(--text-muted);
    font-size: 13.5px;
    max-width: 900px;
    margin-bottom: 16px;
    line-height: 1.7;
  }

  /* Chart containers */
  .chart-grid-2 {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 20px;
    margin-top: 20px;
  }
  @media (max-width: 800px) { .chart-grid-2 { grid-template-columns: 1fr; } }
  .chart-card {
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 8px;
    padding: 20px 22px;
  }
  .chart-card h3 {
    font-size: 13px;
    font-weight: 600;
    color: var(--text-muted);
    text-transform: uppercase;
    letter-spacing: 0.06em;
    margin-bottom: 16px;
  }
  .chart-card .chart-wrap {
    position: relative;
  }

  /* Table */
  .data-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 13px;
    margin-top: 16px;
  }
  .data-table thead tr { background: var(--surface2); }
