  .data-table td {
    padding: 9px 14px;
    border-bottom: 1px solid var(--border);
    color: var(--text-muted);
  }
  .data-table tr:last-child td { border-bottom: none; }
  .data-table tr:hover td { background: var(--surface2); }
  .data-table .name-cell { font-weight: 600; color: var(--text); }
  .data-table .bar-cell { min-width: 120px; }
  .bar-wrap {
    display: flex;
    align-items: center;
    gap: 8px;
