  .bar-fill {
    height: 6px;
    border-radius: 3px;
    background: var(--accent);
    flex-shrink: 0;
  }

  /* Regime pills */
  .regime-badges {
    display: flex;
    gap: 10px;
    flex-wrap: wrap;
    margin-bottom: 20px;
  }
  .regime-badge {
    padding: 8px 16px;
    border-radius: 6px;
    font-size: 13px;
    font-weight: 600;
    display: flex;
    flex-direction: column;
    align-items: center;
    min-width: 90px;
  }
  .regime-badge .r-val { font-size: 22px; font-weight: 700; }
  .regime-badge .r-pct { font-size: 11px; opacity: 0.85; }
  .regime-badge .r-label { font-size: 10px; letter-spacing: 0.08em; text-transform: uppercase; opacity: 0.7; margin-top: 2px; }
  .badge-leo { background: rgba(31,111,235,0.18); border: 1px solid rgba(31,111,235,0.5); color: #58a6ff; }
  .badge-meo { background: rgba(35,134,54,0.18); border: 1px solid rgba(35,134,54,0.5); color: #3fb950; }
  .badge-geo { background: rgba(158,106,3,0.18); border: 1px solid rgba(158,106,3,0.5); color: #e3b341; }
  .badge-heo { background: rgba(185,28,28,0.18); border: 1px solid rgba(185,28,28,0.5); color: #f78166; }

  /* Callout box */
  .callout {
    background: rgba(31,111,235,0.08);
    border-left: 3px solid var(--accent);
    border-radius: 0 6px 6px 0;
    padding: 14px 18px;
    margin: 16px 0;
    font-size: 13px;
    color: var(--text-muted);
  }
  .callout strong { color: var(--text); }

  .callout.orange {
    background: rgba(255,166,87,0.08);
    border-left-color: var(--accent5);
  }
  .callout.green {
    background: rgba(63,185,80,0.08);
