  }

  /* Stats inline */
  .stat-row {
    display: flex;
    gap: 24px;
    flex-wrap: wrap;
    margin: 16px 0;
  }
  .stat-item {
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 6px;
    padding: 10px 16px;
    min-width: 140px;
  }
  .stat-item .s-label { font-size: 11px; color: var(--text-dim); text-transform: uppercase; letter-spacing: 0.06em; }
  .stat-item .s-val { font-size: 18px; font-weight: 700; color: var(--text); }

  /* Methodology note */
  .methodology {
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 6px;
    padding: 12px 16px;
    font-size: 12px;
